def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    segments = []
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            if abs(r2 - r1) == abs(c2 - c1):
                dr = 1 if r2 > r1 else -1
                dc = 1 if c2 > c1 else -1
                length = abs(r2 - r1)
                segments.append((r1, c1, dr, dc))
                for k in range(length + 1):
                    r, c = r1 + k * dr, c1 + k * dc
                    if grid[r][c] != 6:
                        out[r][c] = 1

    # A 6 lying on a 1-to-1 diagonal sends a 6 diagonal perpendicular to it.
    for r, c in sixes:
        for r1, c1, dr, dc in segments:
            if (r - r1) * dc == (c - c1) * dr:
                pdr, pdc = dc, -dr
                for sign in (-1, 1):
                    rr, cc = r, c
                    while 0 <= rr < h and 0 <= cc < w:
                        if grid[rr][cc] != 1:
                            out[rr][cc] = 6
                        rr += sign * pdr
                        cc += sign * pdc
                break
    return out
